]+(.*?)[
]*endstream', re.S)  print('matches', len(list(stream_re.finditer(b))))  keywords = ['preheat','ramp','tal','time above liquidus','liquidus','peak','conveyor','dwell','speed','soak','cool']  texts=[] for m in stream_re.finditer(b):     dct=m.group(1)     s=m.group(2)     out=None     if b'FlateDecode' in dct:         ss=s.strip(b'
')         try:             out=zlib.decompress(ss)         except Exception:             try:                 out=zlib.decompress(ss, -15)             except Exception:                 out=None     else:         out=s     if not out:         continue      # Pull literal strings     buf=out     i=0     while i<len(buf):         if buf[i:i+1]==b'(':             i+=1             depth=1             out_chars=[]             while i<len(buf) and depth>0:                 c=buf[i]                 if c==0x5c:                     i+=1                     if i>=len(buf):                         break                     c2=buf[i]                     if c2 in b'nrtbf':                         out_chars.append({'n':'
','r':'','t':'	','b':' ','f':' '}[chr(c2)])                     elif c2 in b'()\':                         out_chars.append(chr(c2))                     elif 48<=c2<=55:                         oct_digits=bytes([c2])                         for _ in range(2):                             if i+1<len(buf) and 48<=buf[i+1]<=55:                                 i+=1                                 oct_digits += bytes([buf[i]])                             else:                                 break                         out_chars.append(chr(int(oct_digits,8)))                     else:                         out_chars.append(chr(c2))                 elif c==0x28:                     depth+=1                     out_chars.append('(')                 elif c==0x29:                     depth-=1                     if depth>0:                         out_chars.append(')')                 else:                     if 32<=c<=126 or c in (9,10,13):                         out_chars.append(chr(c))                 i+=1             txt=''.join(out_chars).strip()             low=txt.lower()             if any(k in low for k in keywords):                 texts.append(txt)         else:             i+=1  # de-dup seen=set(); uniq=[] for t in texts:     if t and t not in seen:         seen.add(t); uniq.append(t)  print('keyword strings', len(uniq)) for t in uniq[:250]:     print(t) PY

